<?php require __DIR__.'/includes/auth.php';$p=db();if($_SERVER['REQUEST_METHOD']==='POST'){admin_verify_csrf();$act=$_POST['act'];if($act==='save'){$id=(int)$_POST['id'];$slug=admin_slug($_POST['slug']?:$_POST['name']);if($id)$p->prepare('UPDATE categories SET name=?,slug=?,description=?,status=?,sort_order=? WHERE id=?')->execute([$_POST['name'],$slug,$_POST['description'],(int)$_POST['status'],(int)$_POST['sort_order'],$id]);else$p->prepare('INSERT INTO categories(name,slug,description,status,sort_order) VALUES(?,?,?,?,?)')->execute([$_POST['name'],$slug,$_POST['description'],(int)$_POST['status'],(int)$_POST['sort_order']]);header('Location: categories.php');exit;}if($act==='delete'){$p->prepare('DELETE FROM categories WHERE id=?')->execute([(int)$_POST['id']]);header('Location: categories.php');exit;}}$edit=null;if(isset($_GET['id'])){$q=$p->prepare('SELECT * FROM categories WHERE id=?');$q->execute([(int)$_GET['id']]);$edit=$q->fetch();}$rows=$p->query('SELECT * FROM categories ORDER BY sort_order,name')->fetchAll();$page_title='Categories';require __DIR__.'/includes/header.php';?><div class="form"><h3><?= $edit?'Edit':'Add' ?> Category</h3><form method="post"><input type="hidden" name="csrf" value="<?=admin_csrf()?>"><input type="hidden" name="act" value="save"><input type="hidden" name="id" value="<?=admin_e($edit['id']??0)?>"><div class="formgrid"><div class="field"><label>Name</label><input required name="name" value="<?=admin_e($edit['name']??'')?>"></div><div class="field"><label>Slug</label><input name="slug" value="<?=admin_e($edit['slug']??'')?>"></div><div class="field full"><label>Description</label><textarea name="description"><?=admin_e($edit['description']??'')?></textarea></div><div class="field"><label>Status</label><select name="status"><option value="1">Active</option><option value="0" <?=isset($edit)&&!$edit['status']?'selected':''?>>Hidden</option></select></div><div class="field"><label>Sort</label><input type="number" name="sort_order" value="<?=admin_e($edit['sort_order']??0)?>"></div></div><div class="actions"><button class="btn">Save</button></div></form></div><div class="section tablebox"><table class="table"><tr><th>Name</th><th>Slug</th><th>Status</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=admin_e($r['name'])?></td><td><?=admin_e($r['slug'])?></td><td><?=$r['status']?'Active':'Hidden'?></td><td><a class="btn gray" href="?id=<?=$r['id']?>">Edit</a> <form class="inline" method="post"><input type="hidden" name="csrf" value="<?=admin_csrf()?>"><input type="hidden" name="act" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn red" data-confirm="Delete category? Packages will remain without category.">Delete</button></form></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/includes/footer.php';?>